{
  "name": "orders_search",
  "title": "Search orders",
  "description": "Find orders by customer, status or date range. Returns at most `limit` matches. Use orders_get for a single order id.",
  "inputSchema": {
    "type": "object",
    "properties": {
      "customer": { "type": "string", "description": "Customer name or email" },
      "status": { "enum": ["open", "shipped", "cancelled"] },
      "limit": { "type": "integer", "minimum": 1, "maximum": 50, "default": 10 },
      "response_format": { "enum": ["concise", "detailed"], "default": "concise" }
    },
    "additionalProperties": false
  },
  "outputSchema": {
    "type": "object",
    "properties": { "orders": { "type": "array" } },
    "required": ["orders"]
  },
  "annotations": { "readOnlyHint": true, "openWorldHint": false }
}

{
  "jsonrpc": "2.0",
  "id": 8,
  "result": {
    "resultType": "complete",
    "content": [
      { "type": "text", "text": "limit must be between 1 and 50, got 500. Retry with a smaller limit." }
    ],
    "isError": true
  }
}
